<template><form class="grid gap-6 xl:grid-cols-3" @submit.prevent="submit"><div class="space-y-6 xl:col-span-2"><section class="card space-y-4 p-5"><h2 class="font-display text-xl font-extrabold text-navy">Load Data & Status</h2><div class="grid gap-4 md:grid-cols-2"><FormSelect label="Sales Order" v-model="form.sales_order_id" :options="salesOrders"/><FormSelect label="Status" v-model="form.status" :options="statuses"/><FormInput label="Dispatch Date" type="date" v-model="form.dispatch_date"/><FormInput label="DR Number" v-model="form.dr_number"/></div></section><section class="card space-y-4 p-5"><h2 class="font-display text-xl font-extrabold text-navy">Client & Logistics</h2><div class="grid gap-4 md:grid-cols-2"><FormInput label="POD / Batching Plant" v-model="form.pod_location"/><FormSelect label="Operational Area" v-model="form.operational_area_id" :options="operationalAreas"/><FormSelect label="Transport Mode" v-model="form.transport_mode" :options="transportModes"/><FormInput label="Balance" type="number" v-model="form.balance"/></div></section><section class="card space-y-4 p-5"><h2 class="font-display text-xl font-extrabold text-navy">Fleet & Driver</h2><div class="grid gap-4 md:grid-cols-3"><FormSelect label="Hauler" v-model="form.hauler_id" :options="haulers"/><FormSelect label="Vehicle" v-model="form.vehicle_id" :options="vehicles"/><FormSelect label="Driver" v-model="form.driver_id" :options="drivers"/></div><div v-for="item in selectedItems" :key="item.id" class="grid gap-3 rounded border p-3 md:grid-cols-3"><div class="font-bold">{{ item.product.name }}</div><div>Remaining: {{ Number(item.quantity - item.dispatched_quantity).toFixed(2) }}</div><FormInput label="Dispatch Qty" type="number" v-model="qty[item.id]"/></div></section><button class="btn-navy w-full">Submit Dispatch Record</button></div><aside class="space-y-6"><div class="card p-5"><h2 class="font-display text-xl font-extrabold text-navy">Route Map Preview</h2><div class="mt-4 flex h-40 items-center justify-center rounded-lg bg-slate-100 text-sm text-slate-500">Map visualization loading...</div></div><div class="rounded-lg bg-navy p-5 text-white"><div class="text-gold">Fleet Availability</div><div class="mt-4 grid grid-cols-2 gap-3"><div class="rounded-lg bg-white/10 p-4"><b class="text-3xl text-sky-300">42</b><p class="text-xs">Active Trucks</p></div><div class="rounded-lg bg-white/10 p-4"><b class="text-3xl text-gold">08</b><p class="text-xs">Maintenance</p></div></div></div></aside></form></template>
<script>import { Inertia } from '@inertiajs/inertia'; import FormInput from '../FormInput.vue'; import FormSelect from '../FormSelect.vue'; export default{components:{FormInput,FormSelect},props:{dispatch:Object,salesOrders:Array,haulers:Array,vehicles:Array,drivers:Array,operationalAreas:Array,statuses:Array,transportModes:Array},data(){return{qty:{},form:this.dispatch?{...this.dispatch}:{sales_order_id:'',dr_number:'DR-'+Date.now(),dispatch_date:new Date().toISOString().slice(0,10),status:'Pending Dispatch',pod_location:'',hauler_id:'',vehicle_id:'',driver_id:'',balance:0,operational_area_id:'',transport_mode:'Truck',notes:''}}},computed:{selectedOrder(){var id=Number(this.form.sales_order_id); return this.salesOrders.find(function(order){return order.id===id})},selectedItems(){return this.selectedOrder ? this.selectedOrder.items : []}},methods:{submit(){this.form.items=this.selectedItems.map(function(item){return{sales_order_item_id:item.id,quantity:this.qty[item.id] || 0}}.bind(this)).filter(function(item){return Number(item.quantity)>0}); if(this.dispatch){Inertia.put('/dispatches/'+this.dispatch.id,this.form)}else{Inertia.post('/dispatches',this.form)}}}}</script>